package com.aizistral.enigmaticlegacy.entities;

import java.util.UUID;

import javax.annotation.Nullable;

import com.aizistral.enigmaticlegacy.EnigmaticLegacy;
import com.aizistral.enigmaticlegacy.handlers.SoulArchive;
import com.aizistral.enigmaticlegacy.handlers.SuperpositionHandler;
import com.aizistral.enigmaticlegacy.helpers.ItemNBTHelper;
import com.aizistral.enigmaticlegacy.items.SoulCrystal;
import com.aizistral.enigmaticlegacy.items.StorageCrystal;
import com.aizistral.enigmaticlegacy.packets.clients.PacketHandleItemPickup;
import com.aizistral.enigmaticlegacy.packets.clients.PacketRecallParticles;
import com.aizistral.enigmaticlegacy.registries.EnigmaticEntities;
import com.aizistral.enigmaticlegacy.registries.EnigmaticItems;

import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.stats.Stats;
import net.minecraft.tags.ItemTags;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.api.distmarker.OnlyIn;
import net.minecraftforge.common.util.ITeleporter;
import net.minecraftforge.network.NetworkHooks;
import net.minecraftforge.network.PacketDistributor;

/**
 * Modified copy of ItemEntity that has special properties
 * and is not recognized as it's instance.
 * @author Integral
 */

public class PermanentItemEntity extends Entity {
	private static final EntityDataAccessor<ItemStack> ITEM = SynchedEntityData.defineId(PermanentItemEntity.class, EntityDataSerializers.ITEM_STACK);
	private int age;
	private int pickupDelay;
	private int health = 5;
	private UUID thrower;
	private UUID owner;
	private Vec3 position;

	public float hoverStart = (float) (Math.random() * Math.PI * 2.0D);

	public PermanentItemEntity(EntityType<PermanentItemEntity> type, Level world) {
		super(type, world);
	}

	public PermanentItemEntity(Level world, double x, double y, double z) {
		this(EnigmaticEntities.PERMANENT_ITEM_ENTITY, world);
		y = y <= world.getMinBuildHeight() ? world.getMinBuildHeight() + 8 : y;

		this.setPos(x, y, z);
		this.setYRot(this.random.nextFloat() * 360.0F);
		this.setInvulnerable(true);

		this.setNoGravity(true);
		this.position = new Vec3(x, y, z);
	}

	public PermanentItemEntity(Level worldIn, double x, double y, double z, ItemStack stack) {
		this(worldIn, x, y, z);
		this.setItem(stack);
	}

	@OnlyIn(Dist.CLIENT)
	private PermanentItemEntity(PermanentItemEntity p_i231561_1_) {
		super(p_i231561_1_.getType(), p_i231561_1_.level());
		this.setItem(p_i231561_1_.getItem().copy());
		this.copyPosition(p_i231561_1_);
		this.age = p_i231561_1_.age;
		this.hoverStart = p_i231561_1_.hoverStart;
	}

	@OnlyIn(Dist.CLIENT)
	public PermanentItemEntity copy() {
		return new PermanentItemEntity(this);
	}

	@Override
	public boolean dampensVibrations() {
		return this.getItem().is(ItemTags.DAMPENS_VIBRATIONS);
	}

	@Override
	protected Entity.MovementEmission getMovementEmission() {
		return Entity.MovementEmission.NONE;
	}

	@Override
	protected void defineSynchedData() {
		this.getEntityData().define(PermanentItemEntity.ITEM, ItemStack.EMPTY);
	}

	@Override
	public void tick() {
		if (this.getItem().isEmpty()) {
			this.discard();
		} else {
			if (!this.level().isClientSide && this.position != null) {
				if (!this.position().equals(this.position)) {
					this.teleportTo(this.position.x, this.position.y, this.position.z);
				}
			}

			super.tick();

			if (this.pickupDelay > 0 && this.pickupDelay != 32767) {
				--this.pickupDelay;
			}

			this.xo = this.getX();
			this.yo = this.getY();
			this.zo = this.getZ();
			Vec3 vec3d = this.getDeltaMovement();

			if (!this.isNoGravity()) {
				this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.04D, 0.0D));
			}

			if (this.level().isClientSide) {
				this.noPhysics = false;

				this.level().addParticle(ParticleTypes.PORTAL, this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), ((Math.random() - 0.5) * 2.0), ((Math.random() - 0.5) * 2.0), ((Math.random() - 0.5) * 2.0));
			}

			++this.age;

			if (!this.level().isClientSide) {
				double d0 = this.getDeltaMovement().subtract(vec3d).lengthSqr();
				if (d0 > 0.01D) {
					this.hasImpulse = true;
				}
			}

			ItemStack item = this.getItem();

			if (item.isEmpty()) {
				this.discard();
			}

			// Portal Cooldown
			this.setPortalCooldown();
		}
	}

	@Override
	public int getDimensionChangingDelay() {
		return Short.MAX_VALUE;
	}

	@Override
	public Entity changeDimension(ServerLevel server, ITeleporter teleporter) {
		return null;
	}

	@Override
	public boolean canChangeDimensions() {
		return false;
	}

	@Override
	public boolean hurt(DamageSource source, float amount) {
		if (this.level().isClientSide || !this.isAlive())
			return false;

		if (SuperpositionHandler.isAbsolute(source)) {
			EnigmaticLegacy.LOGGER.warn("[WARN] Attacked permanent item entity with absolute DamageSource: " + source);
			this.kill();
			return true;
		} else
			return false;
	}

	@Override
	public void remove(Entity.RemovalReason reason) {
		if (reason == RemovalReason.DISCARDED || reason == RemovalReason.KILLED) {
			EnigmaticLegacy.LOGGER.warn("[WARN] Removing Permanent Item Entity: " + this);

			if (!this.level().isClientSide) {
				SoulArchive.getInstance().removeItem(this);
			}
		}

		super.remove(reason);
	}

	@Override
	public void addAdditionalSaveData(CompoundTag compound) {
		compound.putShort("Health", (short) this.health);
		compound.putShort("Age", (short) this.age);
		compound.putShort("PickupDelay", (short) this.pickupDelay);
		if (this.getThrowerId() != null) {
			compound.putUUID("Thrower", this.getThrowerId());
		}

		if (this.getOwnerId() != null) {
			compound.putUUID("Owner", this.getOwnerId());
		}

		if (!this.getItem().isEmpty()) {
			compound.put("Item", this.getItem().save(new CompoundTag()));
		}

		if (this.position != null) {
			compound.putDouble("BoundX", this.position.x);
			compound.putDouble("BoundY", this.position.y);
			compound.putDouble("BoundZ", this.position.z);
		}
	}

	@Override
	public void readAdditionalSaveData(CompoundTag compound) {
		this.health = compound.getShort("Health");
		this.age = compound.getShort("Age");
		if (compound.contains("PickupDelay")) {
			this.pickupDelay = compound.getShort("PickupDelay");
		}

		if (compound.contains("Owner")) {
			this.owner = compound.getUUID("Owner");
		}

		if (compound.contains("Thrower")) {
			this.thrower = compound.getUUID("Thrower");
		}

		if (compound.contains("BoundX") && compound.contains("BoundY") && compound.contains("BoundZ")) {
			double x = compound.getDouble("BoundX");
			double y = compound.getDouble("BoundY");
			double z = compound.getDouble("BoundZ");
			this.position = new Vec3(x, y, z);
		}

		CompoundTag compoundnbt = compound.getCompound("Item");
		this.setItem(ItemStack.of(compoundnbt));
		if (this.getItem().isEmpty()) {
			this.discard();
		}

	}

	@Override
	public void playerTouch(Player player) {
		if (!this.level().isClientSide) {
			if (this.pickupDelay > 0)
				return;

			ItemStack itemstack = this.getItem();
			Item item = itemstack.getItem();
			int i = itemstack.getCount();

			ItemStack copy = itemstack.copy();
			boolean isPlayerOwner = player.getUUID().equals(this.getOwnerId());
			boolean allowPickUp = false;

			if (item instanceof StorageCrystal && (isPlayerOwner || !EnigmaticItems.ENIGMATIC_AMULET.isVesselOwnerOnly())) {
				allowPickUp = true;
			} else if (item instanceof SoulCrystal && isPlayerOwner) {
				allowPickUp = true;
			}

			if (allowPickUp) {
				if (item instanceof StorageCrystal) {
					CompoundTag crystalNBT = ItemNBTHelper.getNBT(itemstack);
					ItemStack embeddedSoul = crystalNBT.contains("embeddedSoul") ? ItemStack.of(crystalNBT.getCompound("embeddedSoul")) : null;

					if (!isPlayerOwner && embeddedSoul != null)
						return;

					EnigmaticItems.STORAGE_CRYSTAL.retrieveDropsFromCrystal(itemstack, player, embeddedSoul);
					SoulArchive.getInstance().removeItem(this);

					/*
					if (!isPlayerOwner && embeddedSoul != null) {
						PermanentItemEntity droppedSoulCrystal = new PermanentItemEntity(this.world, this.getPosX(), this.getPosY(), this.getPosZ(), embeddedSoul);
						droppedSoulCrystal.setOwnerId(this.getOwnerId());
						this.world.addEntity(droppedSoulCrystal);
					}
					 */

				} else if (item instanceof SoulCrystal) {
					if (!EnigmaticItems.SOUL_CRYSTAL.retrieveSoulFromCrystal(player, itemstack))
						return;
					else {
						SoulArchive.getInstance().removeItem(this);
					}
				}

				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), 64, player.level().dimension())), new PacketRecallParticles(this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), 48, false));

				player.take(this, i);
				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY(), this.getZ(), 64, this.level().dimension())), new PacketHandleItemPickup(player.getId(), this.getId()));

				EnigmaticLegacy.LOGGER.info("Player " + player.getGameProfile().getName() + " picking up: " + this);
				this.discard();
				itemstack.setCount(0);
			} else if (this.pickupDelay == 0 && (this.owner == null || this.owner.equals(player.getUUID())) && (i <= 0 || player.getInventory().add(itemstack))) {
				copy.setCount(copy.getCount() - this.getItem().getCount());
				if (itemstack.isEmpty()) {
					player.take(this, i);

					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY(), this.getZ(), 64, this.level().dimension())), new PacketHandleItemPickup(player.getId(), this.getId()));

					EnigmaticLegacy.LOGGER.info("Player " + player.getGameProfile().getName() + " picking up: " + this);
					this.discard();
					itemstack.setCount(i);
				}

				player.awardStat(Stats.ITEM_PICKED_UP.get(item), i);
			}

		}
	}

	public boolean containsSoul() {
		if (this.getItem().is(EnigmaticItems.SOUL_CRYSTAL))
			return true;
		else if (this.getItem().is(EnigmaticItems.STORAGE_CRYSTAL))
			return ItemNBTHelper.getNBT(this.getItem()).contains("embeddedSoul");
		else
			return false;
	}

	@OnlyIn(Dist.CLIENT)
	public float getItemHover(float partialTicks) {
		return (this.getAge() + partialTicks) / 20.0F + this.hoverStart;
	}

	@Override
	@OnlyIn(Dist.CLIENT)
	public boolean shouldRenderAtSqrDistance(double distance) {
		double d0 = this.getBoundingBox().getSize() * 4.0D;
		if (Double.isNaN(d0)) {
			d0 = 4.0D;
		}

		d0 = d0 * 64.0D;
		return distance < d0 * d0;
	}

	@Override
	public Component getName() {
		Component itextcomponent = this.getCustomName();
		return itextcomponent != null ? itextcomponent : Component.translatable(this.getItem().getDescriptionId());
	}

	@Override
	public boolean isAttackable() {
		return false;
	}

	@Override
	public boolean isCurrentlyGlowing() {
		return true;
	}

	public ItemStack getItem() {
		return this.getEntityData().get(PermanentItemEntity.ITEM);
	}

	public void setItem(ItemStack stack) {
		this.getEntityData().set(PermanentItemEntity.ITEM, stack);
	}

	@Nullable
	public UUID getOwnerId() {
		return this.owner;
	}

	public void setOwnerId(@Nullable UUID ownerId) {
		this.owner = ownerId;
	}

	@Nullable
	public UUID getThrowerId() {
		return this.thrower;
	}

	public void setThrowerId(@Nullable UUID throwerId) {
		this.thrower = throwerId;
	}

	@OnlyIn(Dist.CLIENT)
	public int getAge() {
		return this.age;
	}

	public void setDefaultPickupDelay() {
		this.pickupDelay = 10;
	}

	public void setNoPickupDelay() {
		this.pickupDelay = 0;
	}

	public void setInfinitePickupDelay() {
		this.pickupDelay = 32767;
	}

	public void setPickupDelay(int ticks) {
		this.pickupDelay = ticks;
	}

	public boolean cannotPickup() {
		return this.pickupDelay > 0;
	}

	public void makeFakeItem() {
		this.setInfinitePickupDelay();
	}

	@Override
	public Packet<ClientGamePacketListener> getAddEntityPacket() {
		return NetworkHooks.getEntitySpawningPacket(this);
	}

}

package com.aizistral.enigmaticlegacy.handlers;

import java.io.File;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Type;
import java.nio.charset.Charset;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;

import org.apache.commons.io.FileUtils;
import org.apache.commons.io.IOUtils;

import com.aizistral.enigmaticlegacy.EnigmaticLegacy;
import com.aizistral.enigmaticlegacy.entities.PermanentItemEntity;
import com.aizistral.enigmaticlegacy.registries.EnigmaticItems;
import com.google.common.base.Preconditions;
import com.google.common.collect.HashMultimap;
import com.google.common.collect.Multimap;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.reflect.TypeToken;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.Tuple;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.storage.LevelResource;
import net.minecraftforge.server.ServerLifecycleHooks;

public class SoulArchive {
	private static final Type SOUL_RECORDS_TYPE = new TypeToken<List<SoulData>>(){}.getType();
	private static final Charset UTF8 = Charset.forName("UTF-8");
	private static SoulArchive instance;
	private final File saveFile;
	private final Multimap<ResourceKey<Level>, SoulData> data = HashMultimap.create();

	public SoulArchive(File saveFolder) {
		Preconditions.checkArgument(saveFolder.exists() && saveFolder.isDirectory(),
				"File " + saveFolder + " does not exist or is not a folder!");
		this.saveFile = new File(saveFolder, "soul_archive.json");
	}

	public Optional<Tuple<UUID, BlockPos>> findNearest(Player player, BlockPos pos) {
		var data =  this.data.get(player.level().dimension()).stream()
				.filter(record -> record.type == 0)
				.filter(record -> Objects.equals(record.ownerID, player.getUUID()))
				.reduce((r1, r2) -> pos.distSqr(r1.pos) > pos.distSqr(r2.pos) ? r2 : r1)
				.orElse(null);

		return data != null ? Optional.of(new Tuple<>(data.id, data.pos)) : Optional.empty();
	}

	public Optional<Tuple<UUID, BlockPos>> findNearest(Level level, BlockPos pos) {
		var data =  this.data.get(level.dimension()).stream()
				.filter(record -> record.type == 0)
				.reduce((r1, r2) -> pos.distSqr(r1.pos) > pos.distSqr(r2.pos) ? r2 : r1)
				.orElse(null);

		return data != null ? Optional.of(new Tuple<>(data.id, data.pos)) : Optional.empty();
	}

	public void save() {
		try {
			try (OutputStream out = FileUtils.openOutputStream(this.saveFile, false)) {
				IOUtils.write(this.saveToBytes(), out);
			}
		} catch (Exception ex) {
			EnigmaticLegacy.LOGGER.fatal("FAILED TO SAVE FILE: " + this.saveFile);
			throw new RuntimeException(ex);
		}
	}

	public void load() {
		try {
			if (!this.saveFile.exists() || !this.saveFile.isFile())
				return;

			try (InputStream in = FileUtils.openInputStream(this.saveFile)) {
				byte[] bytes = in.readAllBytes();
				this.loadFromBytes(bytes);
			}
		} catch (Exception ex) {
			EnigmaticLegacy.LOGGER.fatal("FAILED TO LOAD FILE: " + this.saveFile);
			throw new RuntimeException(ex);
		}
	}

	private byte[] saveToBytes() {
		String text = new GsonBuilder().setPrettyPrinting().create().toJson(new ArrayList<>(this.data.values()));
		return text.getBytes(UTF8);
	}

	private void loadFromBytes(byte[] bytes) {
		this.data.clear();

		String text = new String(bytes, UTF8);
		List<SoulData> list =  new Gson().fromJson(text, SOUL_RECORDS_TYPE);

		list.forEach(record -> {
			ResourceKey<Level> key = ResourceKey.create(Registries.DIMENSION, record.dimension);
			this.data.put(key, record);
		});
	}

	private void synchronize() {
		ServerLifecycleHooks.getCurrentServer().getPlayerList().getPlayers().forEach(player -> {
			if (SuperpositionHandler.hasCurio(player, EnigmaticItems.SOUL_COMPASS)) {
				SuperpositionHandler.updateSoulCompass(player);
			}
		});
	}

	public void addItem(PermanentItemEntity item) {
		SoulData record = new SoulData(item.level().dimension().location(), item.getUUID(), item.getOwnerId(),
				item.blockPosition(), item.containsSoul() ? 0 : 1);

		if (this.data.put(item.level().dimension(), record)) {
			this.save();
			this.synchronize();
		}
	}

	public void removeItem(UUID id) {
		if (this.data.values().removeIf(record -> record.id.equals(id))) {
			this.save();
			this.synchronize();
		}
	}

	public void removeItem(PermanentItemEntity item) {
		if (this.data.values().removeIf(record -> record.isEqual(item))) {
			this.save();
			this.synchronize();
		}
	}

	public static SoulArchive getInstance() {
		return instance;
	}

	public static void initialize(MinecraftServer server) {
		instance = new SoulArchive(server.getWorldPath(LevelResource.ROOT).toFile());
		instance.load();
	}

	private static class SoulData {
		private ResourceLocation dimension;
		private UUID id;
		private UUID ownerID;
		private BlockPos pos;
		private int type;

		SoulData(ResourceLocation dimension, UUID id, UUID ownerID, BlockPos pos, int type) {
			this.dimension = dimension;
			this.id = id;
			this.ownerID = ownerID;
			this.pos = pos;
			this.type = type;
		}

		@Override
		public int hashCode() {
			return Objects.hash(this.dimension, this.id, this.ownerID, this.pos, this.type);
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (this.getClass() != obj.getClass())
				return false;
			SoulData other = (SoulData) obj;
			return Objects.equals(this.dimension, other.dimension) && Objects.equals(this.id, other.id) && Objects.equals(this.ownerID, other.ownerID) && Objects.equals(this.pos, other.pos) && this.type == other.type;
		}

		@Override
		public String toString() {
			return "SoulData [dimension=" + this.dimension + ", id=" + this.id + ", ownerID=" + this.ownerID + ", pos=" + this.pos + ", type=" + this.type + "]";
		}

		boolean isEqual(PermanentItemEntity item) {
			return Objects.equals(this.id, item.getUUID()) && Objects.equals(this.ownerID, item.getOwnerId());
		}
	}

}

package com.hollingsworth.arsnouveau.api.registry;

import com.hollingsworth.arsnouveau.api.ritual.AbstractRitual;
import com.hollingsworth.arsnouveau.common.items.RitualTablet;
import net.minecraft.resources.ResourceLocation;

import javax.annotation.Nullable;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class RitualRegistry {

    private static ConcurrentHashMap<ResourceLocation, AbstractRitual> ritualMap = new ConcurrentHashMap<>();

    private static ConcurrentHashMap<ResourceLocation, RitualTablet> ritualItemMap = new ConcurrentHashMap<>();

    public static @Nullable AbstractRitual getRitual(ResourceLocation id) {
        if (!ritualMap.containsKey(id))
            return null;
        try {
            return ritualMap.get(id).getClass().getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

    public static Map<ResourceLocation, AbstractRitual> getRitualMap() {
        return ritualMap;
    }

    public static Map<ResourceLocation, RitualTablet> getRitualItemMap() {
        return ritualItemMap;
    }

    public static AbstractRitual registerRitual(AbstractRitual ritual) {
        return ritualMap.put(ritual.getRegistryName(), ritual);
    }
}

package com.hollingsworth.arsnouveau.api.ritual;

import com.hollingsworth.arsnouveau.ArsNouveau;
import com.hollingsworth.arsnouveau.api.util.BlockUtil;
import com.hollingsworth.arsnouveau.client.particle.ParticleColor;
import com.hollingsworth.arsnouveau.common.block.tile.RitualBrazierTile;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.RandomSource;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.ItemLike;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nullable;
import java.util.*;
import java.util.function.Predicate;

public abstract class AbstractRitual {

    public RitualBrazierTile tile;

    private RitualContext context;

    public RandomSource rand = RandomSource.create();

    public UUID playerUUID;

    public AbstractRitual() {
    }

    public void tryTick(RitualBrazierTile tickingTile) {
        if (tickingTile == null || !getContext().isStarted || getContext().isDone) {
            return;
        }
        this.tile = tickingTile;
        tick();
    }

    public @Nullable BlockPos getPos() {
        return tile != null ? tile.getBlockPos() : null;
    }

    public @Nullable Level getWorld() {
        return tile != null ? tile.getLevel() : null;
    }

    public boolean canStart(@Nullable Player player) {
        return true;
    }

